.relforcerowsecurity OR pg_get_userbyid(c.relowner)<>e.owner OR NOT has_table_privilege(current_user,c.oid,'SELECT')) THEN RAISE EXCEPTION 'Reviewed relation protection, ownership or operator read access changed'; END IF;
