 IF (SELECT jsonb_object_agg(relation,layout) FROM (SELECT c.relname AS relation,jsonb_object_agg(a.attname,jsonb_build_array(CASE WHEN ty.typtype='e' AND tn.nspname='public' THEN ty.typname::text ELSE format_type(a.atttypid,a.atttypmod) END,a.attnotnull)) AS layout FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped JOIN pg_catalog.pg_type ty ON ty.oid=a.atttypid JOIN pg_catalog.pg_namespace tn ON tn.oid=ty.typnamespace WHERE n.nspname='public' AND c.relname IN ('assessment_audit','assessment_scopes','assessment_scores','assessment_subject_roster','assessment_config_versions','assessment_source_write_gate','assessment_operation_receipts','assessment_source_write_claims') GROUP BY c.relname) layouts) IS DISTINCT FROM '{"assessment_audit":{"id":["uuid",true],"action":["character varying(64)",true],"scope_id":["uuid",true],"school_id":["uuid",true],"occurred_at":["timestamp with time zone",true],"after_revision":["integer",true],"before_revision":["integer",true],"actor_membership_id":["uuid",true]},"assessment_scopes":{"id":["uuid",true],"term_id":["uuid",true],"class_id":["uuid",true],"revision":["integer",true],"school_id":["uuid",true],"session_id":["uuid",true]},"assessment_scores":{"id":["uuid",true],"version":["integer",true],"roster_id":["uuid",true],"school_id":["uuid",true],"student_id":["uuid",true],"updated_by":["uuid",true],"component_key":["character varying(128)",true],"enrollment_id":["uuid",true],"numeric_score":["numeric(12,4)",false],"observation_key":["character varying(128)",false],"config_version_id":["uuid",true]},"assessment_subject_roster":{"id":["uuid",true],"scope_id":["uuid",true],"is_active":["boolean",true],"school_id":["uuid",true],"subject_id":["uuid",true],"roster_version":["integer",true],"config_version_id":["uuid",true]},"assessment_config_versions":{"id":["uuid",true],"mode":["assessment_mode",true],"state":["assessment_config_state",true],"grading":["jsonb",true],"term_id":["uuid",true],"level_id":["uuid",true],"revision":["integer",true],"school_id":["uuid",true],"components":["jsonb",true],"config_key":["uuid",true],"session_id":["uuid",true],"subject_id":["uuid",false]},"assessment_source_write_gate":{"id":["integer",true]},"assessment_operation_receipts":{"id":["uuid",true],"outcome":["jsonb",true],"scope_id":["uuid",true],"school_id":["uuid",true],"fingerprint":["character varying(64)",true],"operation_key":["character varying(128)",true],"resulting_revision":["integer",true],"actor_membership_id":["uuid",true]},"assessment_source_write_claims":{"scope_id":["uuid",true],"transaction_id":["text",true]}}'::jsonb THEN RAISE EXCEPTION 'Reviewed score column layout changed'; END IF;
