 IF EXISTS(SELECT 1 FROM jsonb_to_recordset('[{"relation":"academic_sessions","columns":["school_id","id"]},{"relation":"assessment_config_versions","columns":["school_id","id"]},{"relation":"assessment_operation_receipts","columns":["school_id","actor_membership_id","operation_key"]},{"relation":"assessment_scopes","columns":["school_id","class_id","session_id","term_id"]},{"relation":"assessment_scores","columns":["school_id","roster_id","enrollment_id","component_key"]},{"relation":"assessment_source_write_claims","columns":["transaction_id","scope_id"]},{"relation":"assessment_subject_roster","columns":["school_id","id","config_version_id"]},{"relation":"classes","columns":["school_id","id"]},{"relation":"enrollments","columns":["school_id","id","student_id","class_id","session_id"]},{"relation":"enrollments","columns":["school_id","id","student_id"]},{"relation":"memberships","columns":["school_id","id"]}]'::jsonb) e(relation text,columns jsonb) WHERE NOT EXISTS(SELECT 1 FROM pg_catalog.pg_index x JOIN pg_catalog.pg_class c ON c.oid=x.indrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=e.relation AND x.indisunique AND x.indisvalid AND x.indisready AND x.indimmediate AND x.indpred IS NULL AND x.indexprs IS NULL AND ARRAY(SELECT a.attname::text FROM unnest(x.indkey::smallint[]) WITH ORDINALITY k(num,ord) JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum=k.num WHERE k.ord<=x.indnkeyatts ORDER BY k.ord)=ARRAY(SELECT jsonb_array_elements_text(e.columns)))) THEN RAISE EXCEPTION 'Reviewed exact unique key changed'; END IF;
