talog.pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relname IN ('academic_levels','academic_sections','academic_sessions','assessment_audit','assessment_config_versions','assessment_finalizations','assessment_operation_receipts','assessment_scopes','assessment_scores','assessment_source_versions','assessment_source_write_claims','assessment_source_write_gate','assessment_subject_roster','assessment_subjects','assessment_teacher_reviews','assessment_teacher_subjects','attendance_audit','attendance_marks','attendance_receipts','attendance_registers','classes','enrollments','memberships','report_card_audit','report_card_operation_receipts','report_card_releases','report_card_snapshots','report_cards','school_users','schools','students','teacher_class_assignments','terms')) AS column_state,(SELECT jsonb_agg(jsonb_build_object('oid',p.oid,'owner',p.proowner,'definition',pg_get_functiondef(p.oid),'settings',p.proconfig,'acl',(SELECT jsonb_agg(jsonb_build_array(entry_acl.grantee,entry_acl.grantor,entry_acl.privilege_type,entry_acl.is_grantable) ORDER BY entry_acl.grantee,entry_acl.grantor,entry_acl.privilege_type,entry_acl.is_grantable) FROM pg_catalog.aclexplode(CASE WHEN pg_catalog.cardinality(COALESCE(p.proacl,pg_catalog.acldefault('f',p.proowner)))>0 THEN COALESCE(p.proacl,pg_catalog.acldefault('f',p.proowner)) END) entry_acl WHERE NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles nr WHERE nr.oid=entry_acl.grantee AND nr.rolname IN ('greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app')))) ORDER BY p.oid) FROM pg_catalog.pg_proc p WHERE p.oid IN (to_regprocedure('public.assessment_invalidate_parent_rows()'),to_regprocedure('public.assessment_invalidate_source_rows()'),to_regprocedure('public.assessment_lock_source_write()'),to_regprocedure('public.assessment_mark_source_scope(uuid)'),to_regprocedure('public.assessment_reject_source_truncate()'),to_regprocedure('public.deny_attendance_history_change()'),to_regprocedure('public.lock_report_card_actor(uuid)'),to_regprocedure('public.lock_report_card_authority_write_gate()'),to_regprocedure('public.lock_report_card_membership_actor_anchor()'),to_regprocedure('public.read_attendance(uuid,text,date)'),to_regprocedure('public.report_card_guard_release_history()'),to_regprocedure('public.report_card_reject_history()'),to_regprocedure('public.report_card_request_auth_uid()'),to_regprocedure('public.report_card_restrict_runtime_writes()'),to_regprocedure('public.resolve_report_card_actor()'),to_regprocedure('public.resolve_staging_staff_account()'),to_regprocedure('public.save_attendance(uuid,jsonb)'))) AS helper_state,(SELECT jsonb_agg(jsonb_build_object('relation',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND c.relname IN ('academic_levels','academic_sections','academic_sessions','assessment_audit','assessment_config_versions','assessment_finalizations','assessment_operation_receipts','assessment_scopes','assessment_scores','assessment_source_versions','assessment_source_write_claims','assessment_source_write_gate','assessment_subject_roster','assessment_subjects','assessment_teacher_reviews','assessment_teacher_subjects','attendance_audit','attendance_marks','attendance_receipts','attendance_registers','classes','enrollments','memberships','report_card_audit','report_card_operation_receipts','report_card_releases','report_card_snapshots','report_cards','school_users','schools','students','teacher_class_assignments','terms')) AS trigger_state,(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_catalog.pg_policies p WHERE schemaname='public' AND tablename IN ('academic_levels','academic_sections','academic_sessions','assessment_audit','assessment_config_versions','assessment_finalizations','assessment_operation_receipts','assessment_scopes','assessment_scores','assessment_source_versions','assessment_source_write_claims','assessment_source_write_gate','assessment_subject_roster','assessment_subjects','assessment_teacher_reviews','assessment_teacher_subjects','attendance_audit','attendance_marks','attendance_receipts','attendance_registers','classes','enrollments','memberships','report_card_audit','report_card_operation_receipts','report_card_releases','report_card_snapshots','report_cards','school_users','schools','students','teacher_class_assignments','terms') AND policyname NOT IN ('assessment_score_private_read','assessment_score_private_write','assessment_score_private_claims','assessment_score_private_gate')) AS policy_state,(SELECT jsonb_build_object('owner',n.nspowner,'acl',(SELECT jsonb_agg(jsonb_build_array(entry_acl.grantee,entry_acl.grantor,entry_acl.privilege_type,entry_acl.is_grantable) ORDER BY entry_acl.grantee,entry_acl.grantor,entry_acl.privilege_type,entry_acl.is_grantable) FROM pg_catalog.aclexplode(CASE WHEN pg_catalog.cardinality(COALESCE(n.nspacl,pg_catalog.acldefault('n',n.nspowner)))>0 THEN COALESCE(n.nspacl,pg_catalog.acldefault('n',n.nspowner)) END) entry_acl WHERE NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles nr WHERE nr.oid=entry_acl.grantee AND nr.rolname IN ('greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app')))) FROM pg_catalog.pg_namespace n WHERE n.nspname='public') AS schema_state,(SELECT COALESCE(jsonb_agg(to_jsonb(d) ORDER BY d.oid),'[]'::jsonb) FROM pg_catalog.pg_default_acl d WHERE d.defaclnamespace=0 OR d.defaclnamespace='public'::regnamespace) AS default_state,(SELECT jsonb_agg(jsonb_build_object('oid',k.oid,'relation',c.relname,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated) ORDER BY k.oid) FROM pg_catalog.pg_constraint k JOIN pg_catalog.pg_class c ON c.oid=k.conrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('academic_levels','academic_sections','academic_sessions','assessment_audit','assessment_config_versions','assessment_finalizations','assessment_operation_receipts','assessment_scopes','assessment_scores','assessment_source_versions','assessment_source_write_claims','assessment_source_write_gate','assessment_subject_roster','assessment_subjects','assessment_teacher_reviews','assessment_teacher_subjects','attendance_audit','attendance_marks','attendance_receipts','attendance_registers','classes','enrollments','memberships','report_card_audit','report_card_operation_receipts','report_card_releases','report_card_snapshots','report_cards','school_users','schools','students','teacher_class_assignments','terms')) AS constraint_state,(SELECT jsonb_agg(jsonb_build_object('oid',i.indexrelid,'relation',c.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready) ORDER BY i.indexrelid) FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('academic_levels','academic_sections','academic_sessions','assessment_audit','assessment_config_versions','assessment_finalizations','assessment_operation_receipts','assessment_scopes','assessment_scores','assessment_source_versions','assessment_source_write_claims','assessment_source_write_gate','assessment_subject_roster','assessment_subjects','assessment_teacher_reviews','assessment_teacher_subjects','attendance_audit','attendance_marks','attendance_receipts','attendance_registers','classes','enrollments','memberships','report_card_audit','report_card_operation_receipts','report_card_releases','report_card_snapshots','report_cards','school_users','schools','students','teacher_class_assignments','terms')) AS index_state;

-- Phase: managed-role-bootstrap
