CREATE ROLE greenfield_assessment_runtime NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB NOREPLICATION;
CREATE ROLE greenfield_assessment_app LOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB NOREPLICATION PASSWORD NULL;
GRANT greenfield_assessment_owner TO postgres WITH ADMIN FALSE GRANTED BY postgres;
GRANT greenfield_assessment_owner TO postgres WITH INHERIT FALSE GRANTED BY postgres;
