GRANT greenfield_assessment_runtime TO greenfield_assessment_app WITH INHERIT FALSE GRANTED BY postgres;
GRANT greenfield_assessment_runtime TO greenfield_assessment_app WITH SET TRUE GRANTED BY postgres;

