GRANT EXECUTE ON FUNCTION "public"."assessment_invalidate_source_rows"() TO "greenfield_assessment_owner";
CREATE FUNCTION "public"."save_assessment_subject_scores"(verified_auth uuid,cmd jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET row_security=on AS $scores$
DECLARE actor record; sc record; roster record; cfg record; klass record; prior record; old_score record; cell jsonb; component jsonb; canonical jsonb; fingerprint text; result jsonb; before_scores jsonb; audit_id uuid; pupil_count integer; after_revision integer; has_old boolean;
BEGIN
 PERFORM id FROM "public"."assessment_source_write_gate" WHERE id=1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing coordinated assessment source gate'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('greenfield.report-card.authority-gate.v1',0));
 IF cmd IS NULL OR jsonb_typeof(cmd)<>'object' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(cmd))<>10 OR NOT (cmd ?& ARRAY['action','classKey','rosterId','configVersionId','expectedConfigRevision','expectedRosterVersion','expectedScopeRevision','operationKey','reason','scores']) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF cmd->>'action'<>'save_subject_scores' OR jsonb_typeof(cmd->'action')<>'string' OR jsonb_typeof(cmd->'classKey')<>'string' OR cmd->>'classKey' NOT IN ('primary5','creche') OR jsonb_typeof(cmd->'rosterId')<>'string' OR jsonb_typeof(cmd->'configVersionId')<>'string' OR cmd->>'rosterId' !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR cmd->>'configVersionId' !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(cmd->'operationKey')<>'string' OR cmd->>'operationKey' !~ '^[A-Za-z0-9:_-]{8,120}$' OR jsonb_typeof(cmd->'scores')<>'array' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF jsonb_array_length(cmd->'scores') NOT BETWEEN 1 AND 10000 OR (cmd->'reason'<>'null'::jsonb AND (jsonb_typeof(cmd->'reason')<>'string' OR length(btrim(cmd->>'reason')) NOT BETWEEN 1 AND 2000)) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['expectedConfigRevision','expectedRosterVersion','expectedScopeRevision']) k WHERE jsonb_typeof(cmd->k)<>'number' OR cmd->>k !~ '^[1-9][0-9]{0,9}$') THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['expectedConfigRevision','expectedRosterVersion','expectedScopeRevision']) k WHERE (cmd->>k)::numeric>=2147483647) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 FOR cell IN SELECT value FROM jsonb_array_elements(cmd->'scores') LOOP
  IF jsonb_typeof(cell)<>'object' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(cell))<>6 OR NOT (cell ?& ARRAY['studentId','enrollmentId','componentKey','expectedVersion','numericScore','observationKey']) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  IF jsonb_typeof(cell->'studentId')<>'string' OR cell->>'studentId' !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(cell->'enrollmentId')<>'string' OR cell->>'enrollmentId' !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' OR jsonb_typeof(cell->'componentKey')<>'string' OR length(cell->>'componentKey') NOT BETWEEN 1 AND 128 OR btrim(cell->>'componentKey')<>cell->>'componentKey' OR jsonb_typeof(cell->'expectedVersion')<>'number' OR cell->>'expectedVersion' !~ '^(0|[1-9][0-9]{0,9})$' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  IF (cell->>'expectedVersion')::numeric>=2147483647 OR (cell->'numericScore'<>'null'::jsonb AND (jsonb_typeof(cell->'numericScore')<>'string' OR cell->>'numericScore' !~ '^(0|[1-9][0-9]{0,7})(\.[0-9]{1,4})?$')) OR (cell->'observationKey'<>'null'::jsonb AND (jsonb_typeof(cell->'observationKey')<>'string' OR length(cell->>'observationKey') NOT BETWEEN 1 AND 128 OR btrim(cell->>'observationKey')<>cell->>'observationKey')) OR (cell->'numericScore'<>'null'::jsonb AND cell->'observationKey'<>'null'::jsonb) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 END LOOP;
 IF (SELECT count(DISTINCT (s->>'enrollmentId',s->>'componentKey')) FROM jsonb_array_elements(cmd->'scores') s)<>jsonb_array_length(cmd->'scores') THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF (SELECT count(*) FROM "public"."school_users" WHERE auth_user_id=verified_auth)<>1 OR (SELECT count(*) FROM "public"."memberships" m JOIN "public"."school_users" u ON u.id=m.user_id WHERE u.auth_user_id=verified_auth AND m.status='active')<>1 THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 SELECT m.* INTO actor FROM "public"."memberships" m JOIN "public"."school_users" u ON u.id=m.user_id WHERE u.auth_user_id=verified_auth AND m.status='active';
 IF actor.school_id<>'0c594571-74c5-46fe-a835-a9b217a3a199'::uuid OR actor.role NOT IN ('admin','teacher') THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 SELECT c.*,l.stage,l.primary_year INTO klass FROM "public"."classes" c JOIN "public"."academic_levels" l ON l.school_id=c.school_id AND l.id=c.level_id AND l.is_active JOIN "public"."academic_sections" s ON s.school_id=c.school_id AND s.id=c.section_id AND s.level_id=l.id AND s.is_active JOIN "public"."schools" school ON school.id=c.school_id AND school.final_primary_year=5 WHERE c.school_id=actor.school_id AND ((cmd->>'classKey'='primary5' AND c.id='1dbfa5e7-99b8-5094-b1f9-c872477d4bf6'::uuid AND l.stage='primary' AND l.primary_year=5) OR (cmd->>'classKey'='creche' AND c.id='fe6e5a74-b93a-5d00-8115-53b6952153be'::uuid AND l.stage='creche'));
 IF NOT FOUND THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 SELECT s.* INTO sc FROM "public"."assessment_scopes" s JOIN "public"."academic_sessions" y ON y.school_id=s.school_id AND y.id=s.session_id AND y.is_current JOIN "public"."terms" term ON term.school_id=s.school_id AND term.id=s.term_id AND term.session_id=y.id AND term.is_current WHERE s.school_id=actor.school_id AND s.class_id=klass.id AND s.session_id='8a9350ca-95cb-50ca-b750-2d8d5a192044'::uuid AND s.term_id='f7742f7c-ffe4-58ee-8dce-c687ec623330'::uuid FOR UPDATE OF s;
 IF NOT FOUND THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 SELECT r.* INTO roster FROM "public"."assessment_subject_roster" r JOIN "public"."assessment_subjects" subject ON subject.school_id=r.school_id AND subject.id=r.subject_id AND subject.is_active WHERE r.school_id=actor.school_id AND r.scope_id=sc.id AND r.id=(cmd->>'rosterId')::uuid AND r.is_active;
 IF NOT FOUND THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 IF actor.role='teacher' AND (SELECT count(*) FROM "public"."teacher_class_assignments" WHERE school_id=actor.school_id AND teacher_membership_id=actor.id AND class_id=klass.id AND session_id=sc.session_id AND ended_at IS NULL)<>1 THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 IF actor.role='teacher' AND (SELECT count(*) FROM "public"."teacher_class_assignments" a JOIN "public"."assessment_teacher_subjects" link ON link.school_id=a.school_id AND link.class_assignment_id=a.id AND link.roster_id=roster.id AND link.is_active WHERE a.school_id=actor.school_id AND a.teacher_membership_id=actor.id AND a.class_id=klass.id AND a.session_id=sc.session_id AND a.ended_at IS NULL)<>1 THEN RETURN '{"ok":false,"code":"forbidden"}'::jsonb; END IF;
 canonical:=cmd || jsonb_build_object('reason',CASE WHEN cmd->'reason'='null'::jsonb THEN NULL ELSE btrim(cmd->>'reason') END,'scores',(SELECT jsonb_agg(s ORDER BY s->>'enrollmentId',s->>'componentKey') FROM jsonb_array_elements(cmd->'scores') s));
 fingerprint:=encode(sha256(convert_to(canonical::text,'UTF8')),'hex');
 SELECT * INTO prior FROM "public"."assessment_operation_receipts" WHERE school_id=actor.school_id AND actor_membership_id=actor.id AND operation_key=cmd->>'operationKey';
 IF FOUND THEN IF prior.scope_id=sc.id AND prior.fingerprint=fingerprint AND prior.outcome->>'format'='greenfield.assessment.score-save.v1' THEN RETURN (prior.outcome->'result') || '{"kind":"replay"}'::jsonb; ELSE RETURN '{"ok":false,"code":"conflict"}'::jsonb; END IF; END IF;
 IF cmd->'reason'='null'::jsonb AND EXISTS(SELECT 1 FROM "public"."assessment_operation_receipts" WHERE school_id=actor.school_id AND scope_id=sc.id AND outcome->>'format'='greenfield.assessment.score-save.v1' AND outcome#>>'{request,rosterId}'=roster.id::text) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF sc.revision<>(cmd->>'expectedScopeRevision')::integer OR sc.revision>=2147483647 OR roster.roster_version<>(cmd->>'expectedRosterVersion')::integer OR roster.config_version_id<>(cmd->>'configVersionId')::uuid OR EXISTS(SELECT 1 FROM "public"."assessment_source_write_claims" WHERE transaction_id=pg_current_xact_id()::text AND scope_id=sc.id) THEN RETURN '{"ok":false,"code":"conflict"}'::jsonb; END IF;
 SELECT * INTO cfg FROM "public"."assessment_config_versions" WHERE school_id=actor.school_id AND id=roster.config_version_id AND level_id=klass.level_id AND session_id=sc.session_id AND term_id=sc.term_id AND (subject_id IS NULL OR subject_id=roster.subject_id) AND state='finalized' AND revision=(cmd->>'expectedConfigRevision')::integer;
 IF NOT FOUND THEN RETURN '{"ok":false,"code":"conflict"}'::jsonb; END IF;
 IF (klass.stage='primary')<>(cfg.mode='numeric') OR cfg.grading->>'mode' IS DISTINCT FROM cfg.mode::text OR jsonb_typeof(cfg.components)<>'array' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF jsonb_array_length(cfg.components) NOT BETWEEN 1 AND 64 OR (SELECT count(DISTINCT c->>'id') FROM jsonb_array_elements(cfg.components) c)<>jsonb_array_length(cfg.components) OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg.components) c WHERE jsonb_typeof(c->'id') IS DISTINCT FROM 'string' OR length(c->>'id') NOT BETWEEN 1 AND 128 OR btrim(c->>'id')<>c->>'id' OR jsonb_typeof(c->'label') IS DISTINCT FROM 'string' OR btrim(c->>'label')='' OR jsonb_typeof(c->'category') IS DISTINCT FROM 'string' OR c->>'category' NOT IN ('ca','exam','other') OR jsonb_typeof(c->'required') IS DISTINCT FROM 'boolean' OR jsonb_typeof(c->'maximumScore') IS DISTINCT FROM 'number' OR jsonb_typeof(c->'weight') IS DISTINCT FROM 'number' OR c->>'maximumScore' !~ '^(0|[1-9][0-9]{0,7})(\.[0-9]{1,4})?$' OR c->>'weight' !~ '^(0|[1-9][0-9]{0,7})(\.[0-9]{1,4})?$') THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(cfg.components) c WHERE (c->>'maximumScore')::numeric<=0 OR (c->>'weight')::numeric<=0) OR (SELECT sum((c->>'weight')::numeric) FROM jsonb_array_elements(cfg.components) c)<>100 THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF cfg.mode='numeric' THEN
  IF jsonb_typeof(cfg.grading->'bands') IS DISTINCT FROM 'array' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  IF jsonb_array_length(cfg.grading->'bands')<1 OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg.grading->'bands') b WHERE jsonb_typeof(b->'min') IS DISTINCT FROM 'number' OR jsonb_typeof(b->'max') IS DISTINCT FROM 'number' OR jsonb_typeof(b->'label') IS DISTINCT FROM 'string' OR btrim(b->>'label')='') THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  IF EXISTS(SELECT 1 FROM (SELECT (b->>'min')::numeric AS lo,(b->>'max')::numeric AS hi,lag((b->>'max')::numeric) OVER(ORDER BY (b->>'min')::numeric) AS previous,row_number() OVER(ORDER BY (b->>'min')::numeric) AS band_number,count(*) OVER() AS band_count FROM jsonb_array_elements(cfg.grading->'bands') b) bands WHERE lo<0 OR hi>100 OR lo>=hi OR (band_number=1 AND lo<>0) OR (band_number=band_count AND hi<>100) OR (band_number>1 AND previous<>lo)) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 END IF;
 IF cfg.mode='observational' THEN
  IF jsonb_typeof(cfg.grading->'levels') IS DISTINCT FROM 'array' THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  IF jsonb_array_length(cfg.grading->'levels')<2 OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg.grading->'levels') l WHERE jsonb_typeof(l->'id') IS DISTINCT FROM 'string' OR length(btrim(l->>'id')) NOT BETWEEN 1 AND 128 OR jsonb_typeof(l->'label') IS DISTINCT FROM 'string' OR btrim(l->>'label')='') OR (SELECT count(DISTINCT l->>'id') FROM jsonb_array_elements(cfg.grading->'levels') l)<>jsonb_array_length(cfg.grading->'levels') THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 END IF;
 SELECT count(*) INTO pupil_count FROM "public"."enrollments" e JOIN "public"."students" p ON p.school_id=e.school_id AND p.id=e.student_id AND p.status='active' WHERE e.school_id=actor.school_id AND e.class_id=klass.id AND e.session_id=sc.session_id AND e.status='active';
 IF pupil_count=0 OR pupil_count*jsonb_array_length(cfg.components)<>jsonb_array_length(cmd->'scores') OR EXISTS(SELECT 1 FROM "public"."enrollments" e JOIN "public"."students" p ON p.school_id=e.school_id AND p.id=e.student_id AND p.status='active' WHERE e.school_id=actor.school_id AND e.class_id=klass.id AND e.session_id=sc.session_id AND e.status='active' AND (SELECT count(*) FROM "public"."enrollments" other WHERE other.school_id=e.school_id AND other.student_id=e.student_id AND other.session_id=e.session_id AND other.status='active')<>1) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 IF EXISTS(SELECT 1 FROM "public"."assessment_scores" score WHERE score.school_id=actor.school_id AND score.roster_id=roster.id AND score.student_id IN (SELECT student_id FROM "public"."enrollments" WHERE school_id=actor.school_id AND class_id=klass.id AND session_id=sc.session_id AND status='active') AND (score.config_version_id<>cfg.id OR NOT EXISTS(SELECT 1 FROM "public"."enrollments" e WHERE e.school_id=score.school_id AND e.id=score.enrollment_id AND e.student_id=score.student_id AND e.class_id=klass.id AND e.session_id=sc.session_id AND e.status='active') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg.components) c WHERE c->>'id'=score.component_key))) THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 -- Validate every cell/version before the first mutation; the exclusive gate prevents phantoms.
 FOR cell IN SELECT value FROM jsonb_array_elements(cmd->'scores') LOOP
  IF NOT EXISTS(SELECT 1 FROM "public"."enrollments" e JOIN "public"."students" p ON p.school_id=e.school_id AND p.id=e.student_id AND p.status='active' WHERE e.school_id=actor.school_id AND e.id=(cell->>'enrollmentId')::uuid AND e.student_id=(cell->>'studentId')::uuid AND e.class_id=klass.id AND e.session_id=sc.session_id AND e.status='active') THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  SELECT c INTO component FROM jsonb_array_elements(cfg.components) c WHERE c->>'id'=cell->>'componentKey';
  IF NOT FOUND THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  IF cell->'numericScore'='null'::jsonb AND cell->'observationKey'='null'::jsonb THEN IF (component->>'required')::boolean THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  ELSIF cfg.mode='numeric' THEN IF cell->'numericScore'='null'::jsonb OR cell->'observationKey'<>'null'::jsonb OR (cell->>'numericScore')::numeric>(component->>'maximumScore')::numeric THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
  ELSE IF cell->'numericScore'<>'null'::jsonb OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg.grading->'levels') l WHERE l->>'id'=cell->>'observationKey') THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF; END IF;
  SELECT * INTO old_score FROM "public"."assessment_scores" WHERE school_id=actor.school_id AND roster_id=roster.id AND enrollment_id=(cell->>'enrollmentId')::uuid AND component_key=cell->>'componentKey' FOR UPDATE;
  has_old:=FOUND;
  IF (has_old AND (old_score.version<>(cell->>'expectedVersion')::integer OR old_score.student_id<>(cell->>'studentId')::uuid OR old_score.config_version_id<>cfg.id)) OR (NOT has_old AND (cell->>'expectedVersion')::integer<>0) THEN RETURN '{"ok":false,"code":"conflict"}'::jsonb; END IF;
  IF has_old AND cmd->'reason'='null'::jsonb THEN RETURN '{"ok":false,"code":"invalid"}'::jsonb; END IF;
 END LOOP;
 SELECT COALESCE(jsonb_agg(to_jsonb(s)||jsonb_build_object('numeric_score',s.numeric_score::text) ORDER BY s.id),'[]'::jsonb) INTO before_scores FROM "public"."assessment_scores" s WHERE s.school_id=actor.school_id AND s.roster_id=roster.id;
 FOR cell IN SELECT value FROM jsonb_array_elements(canonical->'scores') LOOP
  IF cell->'numericScore'='null'::jsonb AND cell->'observationKey'='null'::jsonb THEN
   DELETE FROM "public"."assessment_scores" WHERE school_id=actor.school_id AND roster_id=roster.id AND enrollment_id=(cell->>'enrollmentId')::uuid AND component_key=cell->>'componentKey';
  ELSIF (cell->>'expectedVersion')::integer=0 THEN
   INSERT INTO "public"."assessment_scores"(school_id,roster_id,config_version_id,enrollment_id,student_id,component_key,numeric_score,observation_key,version,updated_by) VALUES(actor.school_id,roster.id,cfg.id,(cell->>'enrollmentId')::uuid,(cell->>'studentId')::uuid,cell->>'componentKey',(cell->>'numericScore')::numeric,cell->>'observationKey',1,actor.id);
  ELSE
   UPDATE "public"."assessment_scores" SET numeric_score=(cell->>'numericScore')::numeric,observation_key=cell->>'observationKey',version=version+1,updated_by=actor.id WHERE school_id=actor.school_id AND roster_id=roster.id AND enrollment_id=(cell->>'enrollmentId')::uuid AND component_key=cell->>'componentKey' AND version=(cell->>'expectedVersion')::integer;
   IF NOT FOUND THEN RAISE EXCEPTION 'Locked score version changed'; END IF;
  END IF;
 END LOOP;
 PERFORM "public"."assessment_mark_source_scope"(sc.id);
 SELECT revision INTO after_revision FROM "public"."assessment_scopes" WHERE id=sc.id AND school_id=actor.school_id;
 IF after_revision IS DISTINCT FROM sc.revision+1 THEN RAISE EXCEPTION 'Assessment save must invalidate its scope exactly once'; END IF;
 audit_id:=gen_random_uuid();
 INSERT INTO "public"."assessment_audit"(id,school_id,scope_id,actor_membership_id,action,before_revision,after_revision) VALUES(audit_id,actor.school_id,sc.id,actor.id,'save_subject_scores',sc.revision,after_revision);
 result:=jsonb_build_object('ok',true,'kind','applied','revision',after_revision);
 INSERT INTO "public"."assessment_operation_receipts"(school_id,scope_id,actor_membership_id,operation_key,fingerprint,resulting_revision,outcome) VALUES(actor.school_id,sc.id,actor.id,cmd->>'operationKey',fingerprint,after_revision,jsonb_build_object('format','greenfield.assessment.score-save.v1','auditId',audit_id,'request',canonical,'beforeScores',before_scores,'result',result));
 RETURN result;
END $scores$;
REVOKE ALL ON FUNCTION "public"."save_assessment_subject_scores"(uuid,jsonb) FROM PUBLIC;

-- Phase: new-function-default-acl-reset
DO $new_api_acl$ DECLARE item record; principal text; BEGIN
 FOR item IN SELECT a.grantee FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(p.proacl,pg_catalog.acldefault('f',p.proowner))) a WHERE p.oid='public.save_assessment_subject_scores(uuid,jsonb)'::regprocedure AND a.grantee<>(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=current_user) LOOP
 principal:=CASE WHEN item.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(item.grantee)) END;
 EXECUTE format('REVOKE ALL ON FUNCTION public.save_assessment_subject_scores(uuid,jsonb) FROM %s',principal);
 END LOOP; END $new_api_acl$;

-- Phase: deferred-ownership-and-cleanup
GRANT EXECUTE ON FUNCTION public.save_assessment_subject_scores(uuid,jsonb) TO greenfield_assessment_runtime;
ALTER FUNCTION public.save_assessment_subject_scores(uuid,jsonb) OWNER TO greenfield_assessment_owner;
SET LOCAL ROLE greenfield_assessment_owner;
DO $unbound_score$ BEGIN IF public.save_assessment_subject_scores(NULL,'{}'::jsonb) IS DISTINCT FROM '{"ok":false,"code":"invalid"}'::jsonb THEN RAISE EXCEPTION 'Unbound score API must reject'; END IF; END $unbound_score$;
RESET ROLE;
DO $rolled_back_score_probes$ DECLARE spec record; cmd jsonb; applied jsonb; replayed jsonb; rejected jsonb; probes integer:=0; BEGIN
 FOR spec IN SELECT r.id AS roster_id,r.roster_version,r.config_version_id,cfg.revision AS config_revision,cfg.components,s.revision,s.class_id,s.session_id,s.id AS scope_id FROM public.assessment_subject_roster r JOIN public.assessment_scopes s ON s.school_id=r.school_id AND s.id=r.scope_id JOIN public.assessment_config_versions cfg ON cfg.school_id=r.school_id AND cfg.id=r.config_version_id WHERE r.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid AND r.is_active AND s.class_id IN ('1dbfa5e7-99b8-5094-b1f9-c872477d4bf6'::uuid,'fe6e5a74-b93a-5d00-8115-53b6952153be'::uuid) AND s.session_id='8a9350ca-95cb-50ca-b750-2d8d5a192044'::uuid AND s.term_id='f7742f7c-ffe4-58ee-8dce-c687ec623330'::uuid ORDER BY r.id LOOP
  cmd:=jsonb_build_object('action','save_subject_scores','classKey',CASE WHEN spec.class_id='1dbfa5e7-99b8-5094-b1f9-c872477d4bf6'::uuid THEN 'primary5' ELSE 'creche' END,'rosterId',spec.roster_id,'configVersionId',spec.config_version_id,'expectedConfigRevision',spec.config_revision,'expectedRosterVersion',spec.roster_version,'expectedScopeRevision',spec.revision,'operationKey','managed-score-rehearsal-'||spec.roster_id::text,'reason','Managed rollback rehearsal only','scores',(SELECT jsonb_agg(jsonb_build_object('studentId',e.student_id,'enrollmentId',e.id,'componentKey',c->>'id','expectedVersion',COALESCE(score.version,0),'numericScore',score.numeric_score::text,'observationKey',score.observation_key) ORDER BY e.id,c->>'id') FROM public.enrollments e JOIN public.students pupil ON pupil.school_id=e.school_id AND pupil.id=e.student_id AND pupil.status='active' CROSS JOIN LATERAL jsonb_array_elements(spec.components) c LEFT JOIN public.assessment_scores score ON score.school_id=e.school_id AND score.enrollment_id=e.id AND score.student_id=e.student_id AND score.roster_id=spec.roster_id AND score.component_key=c->>'id' WHERE e.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid AND e.class_id=spec.class_id AND e.session_id=spec.session_id AND e.status='active'));
  BEGIN
   SET LOCAL ROLE greenfield_assessment_owner;
   applied:=public.save_assessment_subject_scores('6448c80e-ed5c-41a4-bcf5-39fd0dfb5b61'::uuid,cmd);
   IF applied IS DISTINCT FROM jsonb_build_object('ok',true,'kind','applied','revision',spec.revision+1) THEN RAISE EXCEPTION 'Managed fictional teacher score probe failed'; END IF;
   replayed:=public.save_assessment_subject_scores('6448c80e-ed5c-41a4-bcf5-39fd0dfb5b61'::uuid,cmd);
   IF replayed IS DISTINCT FROM jsonb_build_object('ok',true,'kind','replay','revision',spec.revision+1) THEN RAISE EXCEPTION 'Managed score replay probe failed'; END IF;
   rejected:=public.save_assessment_subject_scores('6448c80e-ed5c-41a4-bcf5-39fd0dfb5b61'::uuid,cmd||jsonb_build_object('reason','Changed payload must conflict'));
   IF rejected IS DISTINCT FROM '{"ok":false,"code":"conflict"}'::jsonb THEN RAISE EXCEPTION 'Managed score changed-key probe failed'; END IF;
   rejected:=public.save_assessment_subject_scores('ee29b64a-37fe-44a1-9285-af6a37088415'::uuid,cmd);
   IF rejected IS DISTINCT FROM '{"ok":false,"code":"forbidden"}'::jsonb THEN RAISE EXCEPTION 'Managed bursar score probe failed'; END IF;
   RESET ROLE;
   -- The exception subtransaction undoes every score/version/claim/audit/receipt write.
   RAISE EXCEPTION USING ERRCODE='ZGS01',MESSAGE='Intentional score probe rollback';
  EXCEPTION WHEN SQLSTATE 'ZGS01' THEN NULL;
  END;
  IF current_user<>'postgres' THEN RAISE EXCEPTION 'Score probe role did not roll back'; END IF;
  probes:=probes+1;
 END LOOP;
 IF probes<>3 THEN RAISE EXCEPTION 'Expected exact three reviewed subject rosters'; END IF;
END $rolled_back_score_probes$;
REVOKE CREATE ON SCHEMA public FROM greenfield_assessment_owner;
REVOKE greenfield_assessment_owner FROM postgres GRANTED BY postgres;

-- Phase: in-transaction-verification
DO $verify$ DECLARE role_name text; relation_name text; signature_name text; permission_name text; column_row record; allowed boolean; BEGIN
 IF (SELECT count(*) FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app') AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication AND NOT rolinherit AND rolcanlogin=(rolname='greenfield_assessment_app'))<>3 THEN RAISE EXCEPTION 'Assessment role flags differ'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE r.rolname IN ('greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app'))<>4 OR (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid=m.roleid JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles g ON g.oid=m.grantor WHERE r.rolname IN ('greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app') AND u.rolname='postgres' AND m.admin_option AND NOT m.inherit_option AND NOT m.set_option AND g.rolsuper)<>3 THEN RAISE EXCEPTION 'Managed bootstrap membership changed'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member WHERE u.rolname IN ('greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app'))<>1 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE u.rolname='greenfield_assessment_app' AND r.rolname='greenfield_assessment_runtime' AND m.set_option AND NOT m.inherit_option AND NOT m.admin_option) THEN RAISE EXCEPTION 'Assessment LOGIN must be SET-only'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc WHERE oid='public.save_assessment_subject_scores(uuid,jsonb)'::regprocedure AND proowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='greenfield_assessment_owner') AND prosecdef AND proconfig @> ARRAY['search_path=pg_catalog','row_security=on']) OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(p.proacl) a WHERE p.oid='public.save_assessment_subject_scores(uuid,jsonb)'::regprocedure AND a.grantee<>p.proowner AND NOT (a.grantee=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='greenfield_assessment_runtime') AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)) THEN RAISE EXCEPTION 'Private assessment API ownership/ACL changed'; END IF;
 FOREACH role_name IN ARRAY ARRAY['greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app'] LOOP
 IF has_schema_privilege(role_name,'public','CREATE') OR has_schema_privilege(role_name,'auth','USAGE') THEN RAISE EXCEPTION 'Unexpected assessment schema privilege'; END IF;
 END LOOP;
 FOREACH role_name IN ARRAY ARRAY['greenfield_assessment_app','greenfield_assessment_runtime'] LOOP
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('academic_levels','academic_sections','academic_sessions','assessment_audit','assessment_config_versions','assessment_finalizations','assessment_operation_receipts','assessment_scopes','assessment_scores','assessment_source_versions','assessment_source_write_claims','assessment_source_write_gate','assessment_subject_roster','assessment_subjects','assessment_teacher_reviews','assessment_teacher_subjects','attendance_audit','attendance_marks','attendance_receipts','attendance_registers','classes','enrollments','memberships','report_card_audit','report_card_operation_receipts','report_card_releases','report_card_snapshots','report_cards','school_users','schools','students','teacher_class_assignments','terms') AND (has_table_privilege(role_name,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') OR has_any_column_privilege(role_name,c.oid,'SELECT,INSERT,UPDATE,REFERENCES'))) OR EXISTS(SELECT 1 FROM pg_catalog.pg_shdepend d WHERE d.refclassid='pg_catalog.pg_authid'::regclass AND d.refobjid=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname=role_name) AND d.deptype='o') THEN RAISE EXCEPTION 'Execution role has data/ownership privileges'; END IF;
 END LOOP;
 FOREACH role_name IN ARRAY ARRAY['greenfield_app','greenfield_report_card_runtime','greenfield_report_card_authority_owner','greenfield_attendance_app','greenfield_attendance_runtime','greenfield_attendance_owner','greenfield_assessment_app','anon','authenticated','service_role'] LOOP
 IF has_function_privilege(role_name,'public.save_assessment_subject_scores(uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Unexpected assessment API execution: %',role_name; END IF;
 END LOOP;
 IF NOT has_function_privilege('greenfield_assessment_runtime','public.save_assessment_subject_scores(uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Missing private API execution'; END IF;
 FOREACH signature_name IN ARRAY ARRAY['public.assessment_invalidate_parent_rows()','public.assessment_invalidate_source_rows()','public.assessment_lock_source_write()','public.assessment_mark_source_scope(uuid)','public.assessment_reject_source_truncate()','public.deny_attendance_history_change()','public.lock_report_card_actor(uuid)','public.lock_report_card_authority_write_gate()','public.lock_report_card_membership_actor_anchor()','public.read_attendance(uuid,text,date)','public.report_card_guard_release_history()','public.report_card_reject_history()','public.report_card_request_auth_uid()','public.report_card_restrict_runtime_writes()','public.resolve_report_card_actor()','public.resolve_staging_staff_account()','public.save_attendance(uuid,jsonb)'] LOOP
 IF has_function_privilege('greenfield_assessment_owner',signature_name,'EXECUTE') IS DISTINCT FROM (signature_name=ANY(ARRAY['public.assessment_lock_source_write()','public.assessment_mark_source_scope(uuid)','public.assessment_invalidate_source_rows()'])) OR has_function_privilege('greenfield_assessment_runtime',signature_name,'EXECUTE') OR has_function_privilege('greenfield_assessment_app',signature_name,'EXECUTE') THEN RAISE EXCEPTION 'Unexpected existing helper privilege change'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(p.proacl) a JOIN pg_catalog.pg_roles nr ON nr.oid=a.grantee WHERE p.oid IN (to_regprocedure('public.assessment_invalidate_parent_rows()'),to_regprocedure('public.assessment_invalidate_source_rows()'),to_regprocedure('public.assessment_lock_source_write()'),to_regprocedure('public.assessment_mark_source_scope(uuid)'),to_regprocedure('public.assessment_reject_source_truncate()'),to_regprocedure('public.deny_attendance_history_change()'),to_regprocedure('public.lock_report_card_actor(uuid)'),to_regprocedure('public.lock_report_card_authority_write_gate()'),to_regprocedure('public.lock_report_card_membership_actor_anchor()'),to_regprocedure('public.read_attendance(uuid,text,date)'),to_regprocedure('public.report_card_guard_release_history()'),to_regprocedure('public.report_card_reject_history()'),to_regprocedure('public.report_card_request_auth_uid()'),to_regprocedure('public.report_card_restrict_runtime_writes()'),to_regprocedure('public.resolve_report_card_actor()'),to_regprocedure('public.resolve_staging_staff_account()'),to_regprocedure('public.save_attendance(uuid,jsonb)')) AND nr.rolname IN ('greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app') AND NOT (nr.rolname='greenfield_assessment_owner' AND p.oid IN ('public.assessment_lock_source_write()'::regprocedure,'public.assessment_mark_source_scope(uuid)'::regprocedure,'public.assessment_invalidate_source_rows()'::regprocedure) AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)) THEN RAISE EXCEPTION 'Unexpected new-role helper ACL or grant option'; END IF;
 FOREACH relation_name IN ARRAY ARRAY['attendance_registers','attendance_marks','attendance_audit','attendance_receipts','report_cards','report_card_snapshots','report_card_audit','report_card_operation_receipts','report_card_releases','assessment_source_versions','assessment_teacher_reviews','assessment_finalizations'] LOOP
