 FOREACH relation_name IN ARRAY ARRAY['academic_levels','academic_sections','academic_sessions','assessment_audit','assessment_config_versions','assessment_finalizations','assessment_operation_receipts','assessment_scopes','assessment_scores','assessment_source_versions','assessment_source_write_claims','assessment_source_write_gate','assessment_subject_roster','assessment_subjects','assessment_teacher_reviews','assessment_teacher_subjects','attendance_audit','attendance_marks','attendance_receipts','attendance_registers','classes','enrollments','memberships','report_card_audit','report_card_operation_receipts','report_card_releases','report_card_snapshots','report_cards','school_users','schools','students','teacher_class_assignments','terms'] LOOP
