   IF has_table_privilege('greenfield_assessment_owner','public.'||relation_name,permission_name) IS DISTINCT FROM allowed THEN RAISE EXCEPTION 'Unexpected private score table privilege: %.%',relation_name,permission_name; END IF;
  END LOOP;
