 IF EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_assessment_owner','greenfield_assessment_runtime','greenfield_assessment_app')) OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='save_assessment_subject_scores') OR EXISTS(SELECT 1 FROM pg_catalog.pg_policies WHERE schemaname='public' AND policyname IN ('assessment_score_private_read','assessment_score_private_write','assessment_score_private_claims','assessment_score_private_gate')) THEN RAISE EXCEPTION 'Score rollback left new objects'; END IF;
END $rolled_back$;
SELECT jsonb_build_object('assessment_score_managed_rollback','PASS','new_assessment_objects_absent',true,'existing_report_source_attendance_state_checked',true,'login_password_configured',false,'assessment_save_enabled',false) AS assessment_score_rollback_result;
